action.command:
powershell -Command "
  # Get the saved file path from stdin
  \$context = \$input | ConvertFrom-Json
  \$filePath = \$context.filePath

  # Only validate source files, not build output or node_modules
  if (\$filePath -match '(node_modules|dist|build|\.next)') {
    exit 0
  }

  Write-Host \"🔍 Validating: \$filePath\" -ForegroundColor Cyan

  \$errors = \$false

  # 1. TypeScript type checking
  Write-Host \"  → TypeScript check...\" -ForegroundColor Gray
  \$tsOutput = npx tsc --noEmit 2>&1
  if (\$LASTEXITCODE -ne 0) {
    Write-Host \"❌ TypeScript errors found:\" -ForegroundColor Red
    Write-Host \$tsOutput -ForegroundColor Red
    \$errors = \$true
  } else {
    Write-Host \"  ✓ TypeScript OK\" -ForegroundColor Green
  }

  # 2. ESLint
  if (Test-Path '.eslintrc*') {
    Write-Host \"  → ESLint check...\" -ForegroundColor Gray
    \$lintOutput = npx eslint \$filePath 2>&1
    if (\$LASTEXITCODE -ne 0) {
      Write-Host \"❌ ESLint errors found:\" -ForegroundColor Red
      Write-Host \$lintOutput -ForegroundColor Red
      \$errors = \$true
    } else {
      Write-Host \"  ✓ ESLint OK\" -ForegroundColor Green
    }
  }

  # 3. Run tests if test file exists
  if (Test-Path '*.test.ts' -o Test-Path '*.spec.ts' -o Test-Path '*.test.tsx' -o Test-Path '*.spec.tsx') {
    Write-Host \"  → Running tests...\" -ForegroundColor Gray
    \$testOutput = npx vitest run 2>&1
    if (\$LASTEXITCODE -ne 0) {
      Write-Host \"❌ Tests failed:\" -ForegroundColor Red
      Write-Host \$testOutput -ForegroundColor Red
      \$errors = \$true
    } else {
      Write-Host \"  ✓ Tests passed\" -ForegroundColor Green
    }
  }

  if (\$errors) {
    Write-Host \"\" 
    Write-Host \"⚠️  Validation issues found. Review and fix the root cause.\" -ForegroundColor Yellow
    exit 0
  } else {
    Write-Host \"✅ All checks passed\" -ForegroundColor Green
    exit 0
  }
"
